package com.ridex.location.dto.request;
import jakarta.validation.*; import org.junit.jupiter.api.*; import static org.junit.jupiter.api.Assertions.*;
class NearbyDriversRequestValidationTest { Validator validator; @BeforeEach void setup(){validator=Validation.buildDefaultValidatorFactory().getValidator();} @Test void acceptsValidRequest(){assertTrue(validator.validate(new NearbyDriversRequest(12.0,77.0,5.0)).isEmpty());} @Test void rejectsInvalidCoordinates(){assertFalse(validator.validate(new NearbyDriversRequest(91.0,0.0,5.0)).isEmpty());assertFalse(validator.validate(new NearbyDriversRequest(0.0,181.0,5.0)).isEmpty());} @Test void rejectsRadiusOutsideOneToFifty(){assertFalse(validator.validate(new NearbyDriversRequest(0.0,0.0,0.0)).isEmpty());assertFalse(validator.validate(new NearbyDriversRequest(0.0,0.0,51.0)).isEmpty());} @Test void rejectsNullFields(){assertEquals(3,validator.validate(new NearbyDriversRequest(null,null,null)).size());} }
